var i=`1102-khao-jee-pate`;var a=`world-1102`;var r=`LA`;var s=`southeast-asia`;var n=4;var o=70;var g={en:`Khao Jee Pâté`,ua:`Кхао джі пате`};var l={en:`Khao Jee Pâté is a dish from Laos prepared with pork loin, fish sauce, garlic, cucumber. This is a home-scale version with measured ingredients in the individual steps where they are used. Prepared liver sausage substitutes for pâté in the Lao-style baguette.`,ua:`Кхао джі пате, страва кухні країни Лаос, яку готують із таких продуктів: свиняча корейка, рибний соус, часник, огірок. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. У лаоському багеті ліверна ковбаса замінює паштет.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 40 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 40 хвилин.`,t:[`marinating`],m:40,i:[[`pork-loin`,700,`g`],[`fish-sauce`,30,`ml`],[`garlic`,4,`clove`],[`white-granulated-sugar`,16,`g`]]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:18,i:[]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:7,i:[[`cucumber`,170,`g`],[`carrot`,150,`g`],[`cilantro`,25,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`baguette`,4,`pcs`],[`mayonnaise`,110,`g`],[`liver-sausage`,100,`g`]]}];var h={slug:i,id:a,country:`LA`,region:s,servings:4,minutes:70,title:g,text:l,steps:u};export{r as country,h as default,a as id,o as minutes,s as region,n as servings,i as slug,u as steps,l as text,g as title};